@namespace sv_23742be5d26d4d1a808859a7b3e13730.Components.Pages.Apply

<section class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <ReferenceForm
            Index="index"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            CanRemove="@(References.Count > 2)"
            OnRemove="() => RemoveReference(index)"
            OnChanged="data => UpdateReference(index, data)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        References[index] = new ReferenceModel
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
            || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone)))
        {
            ErrorMessage = "All reference fields are required.";
            return;
        }

        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

