toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
::deep .step-indicator {
    margin-bottom: 2rem;
}

::deep .step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .step-item {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

::deep .step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem;
    font-size: 0.85rem;
    color: inherit;
}

::deep .step-item.completed .step-button {
    cursor: pointer;
    color: #16a34a;
}

::deep .step-item.completed .step-button:hover {
    text-decoration: underline;
}

::deep .step-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: bold;
    border: 2px solid #d1d5db;
    background: #fff;
}

::deep .step-item.current .step-icon {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

::deep .step-item.completed .step-icon {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

::deep .step-item.future .step-icon {
    opacity: 0.5;
}

::deep .step-item.future .step-label {
    opacity: 0.5;
}

::deep .step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    min-width: 1rem;
}

::deep .step-connector.completed {
    background: #16a34a;
}

/* Step Content */
::deep .step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 2rem;
}

::deep .step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

/* Form Elements */
::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
