@namespace sv_23742be5d26d4d1a808859a7b3e13730.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label for="company-@Index">Company Name *</label>
        <input id="company-@Index" type="text" value="@Company" @onchange="OnCompanyChanged" required />
    </div>

    <div class="form-group">
        <label for="title-@Index">Job Title *</label>
        <input id="title-@Index" type="text" value="@Title" @onchange="OnTitleChanged" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label for="start-@Index">Start Date *</label>
            <input id="start-@Index" type="date" value="@FormatDate(StartDate)" @onchange="OnStartDateChanged" required />
        </div>

        <div class="form-group">
            <label for="end-@Index">End Date</label>
            <input id="end-@Index" type="date" value="@FormatDate(EndDate)" @onchange="OnEndDateChanged" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="desc-@Index">Description</label>
        <textarea id="desc-@Index" rows="3" value="@Description" @onchange="OnDescriptionChanged"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter, EditorRequired] public string Company { get; set; } = string.Empty;
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter, EditorRequired] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter, EditorRequired] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private static string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
